#include <vector>
#include <iostream>

int main() {
    // Original container
    std::vector<int> original = {1, 2, 3, 4, 5};

    // Direct copy: Creates a new vector with the same elements and type
    std::vector<int> copyVec = original;  // Best for identical containers, e.g., for backups

    // Iterator-based copy: Copies to a new container with a different type
    std::vector<double> doubleVec(original.begin(), original.end());  // Converts int to double for potential use in calculations

    // Output to verify
    std::cout << "Original: ";
    for (int elem : original) std::cout << elem << " ";
    std::cout << std::endl;

    std::cout << "Copied (int): ";
    for (int elem : copyVec) std::cout << elem << " ";
    std::cout << std::endl;

    std::cout << "Copied and converted (double): ";
    for (double elem : doubleVec) std::cout << elem << " ";
    std::cout << std::endl;

    return 0;
}
